package kr.memorynotes;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
public class ImageMaskView extends View {
 final JSONObject image;final Bitmap bitmap;final Paint p=new Paint(3);final RectF fit=new RectF();boolean hidden,editing;boolean fitContentWidth;float startX,startY,endX,endY;boolean dragging;float zoom=1,panX=0,panY=0,lastX,lastY;ScaleGestureDetector scale;
 ImageMaskView(Context c,JSONObject image,boolean hidden,boolean editing){super(c);this.image=image;this.hidden=hidden;this.editing=editing;BitmapFactory.Options o=new BitmapFactory.Options();String path=new File(new File(c.getFilesDir(),"images"),image.optString("file")).getPath();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(path,o);int sample=1;while(o.outWidth/sample>2048||o.outHeight/sample>2048)sample*=2;o.inSampleSize=sample;o.inJustDecodeBounds=false;bitmap=BitmapFactory.decodeFile(path,o);setContentDescription(editing?"사진. 드래그하여 가림 영역 지정":"첨부 사진. 확대 화면에서 두 손가락으로 확대");scale=new ScaleGestureDetector(c,new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){zoom=Math.max(1,Math.min(5,zoom*d.getScaleFactor()));invalidate();return true;}});}
 protected void onMeasure(int widthSpec,int heightSpec){if(fitContentWidth&&bitmap!=null&&MeasureSpec.getMode(widthSpec)!=MeasureSpec.UNSPECIFIED){int width=MeasureSpec.getSize(widthSpec);int height=Math.max(1,(int)Math.round((double)bitmap.getHeight()*width/bitmap.getWidth()));setMeasuredDimension(width,resolveSize(height,heightSpec));}else super.onMeasure(widthSpec,heightSpec);}
 protected void onDraw(Canvas canvas){super.onDraw(canvas);if(bitmap==null){p.setColor(Color.GRAY);p.setTextSize(32);canvas.drawText("사진을 불러올 수 없습니다",12,50,p);return;}float s=Math.min((float)getWidth()/bitmap.getWidth(),(float)getHeight()/bitmap.getHeight());float w=bitmap.getWidth()*s,h=bitmap.getHeight()*s;fit.set((getWidth()-w)/2,(getHeight()-h)/2,(getWidth()+w)/2,(getHeight()+h)/2);canvas.save();if(!editing){canvas.translate(panX,panY);canvas.scale(zoom,zoom,getWidth()/2f,getHeight()/2f);}canvas.drawBitmap(bitmap,null,fit,p);JSONArray masks=image.optJSONArray("masks");if(masks!=null&&(hidden||editing))for(int i=0;i<masks.length();i++){JSONArray m=masks.optJSONArray(i);if(m==null)continue;p.setColor(editing?0x99257967:0xFF203B32);canvas.drawRoundRect(rect(m),7,7,p);}if(dragging){p.setColor(0xAA257967);canvas.drawRect(Math.min(startX,endX),Math.min(startY,endY),Math.max(startX,endX),Math.max(startY,endY),p);}canvas.restore();}
 RectF rect(JSONArray m){return new RectF(fit.left+(float)m.optDouble(0)*fit.width(),fit.top+(float)m.optDouble(1)*fit.height(),fit.left+(float)m.optDouble(2)*fit.width(),fit.top+(float)m.optDouble(3)*fit.height());}
 float clamp(float n,float low,float high){return Math.max(low,Math.min(n,high));}
 public boolean onTouchEvent(android.view.MotionEvent e){if(bitmap==null)return false;if(!editing){scale.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=e.getX();lastY=e.getY();return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE&&!scale.isInProgress()){if(zoom>1){panX+=e.getX()-lastX;panY+=e.getY()-lastY;}lastX=e.getX();lastY=e.getY();invalidate();return true;}return true;}if(e.getAction()==MotionEvent.ACTION_DOWN){if(!fit.contains(e.getX(),e.getY()))return false;startX=endX=e.getX();startY=endY=e.getY();dragging=true;getParent().requestDisallowInterceptTouchEvent(true);return true;}if(e.getAction()==MotionEvent.ACTION_MOVE&&dragging){endX=clamp(e.getX(),fit.left,fit.right);endY=clamp(e.getY(),fit.top,fit.bottom);invalidate();return true;}if((e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL)&&dragging){dragging=false;if(e.getAction()==MotionEvent.ACTION_UP&&Math.abs(endX-startX)>12&&Math.abs(endY-startY)>12){JSONArray m=new JSONArray();try{m.put((Math.min(startX,endX)-fit.left)/fit.width());m.put((Math.min(startY,endY)-fit.top)/fit.height());m.put((Math.max(startX,endX)-fit.left)/fit.width());m.put((Math.max(startY,endY)-fit.top)/fit.height());if(image.optJSONArray("masks")==null)image.put("masks",new JSONArray());image.getJSONArray("masks").put(m);}catch(Exception ex){throw new IllegalStateException(ex);}}invalidate();return true;}return true;}
 static boolean hasSeparateImages(Note n){java.util.List<String> inline=InlineImageText.files(n.body+"\n"+n.answer);for(int i=0;i<n.images.length();i++){JSONObject im=n.images.optJSONObject(i);if(im!=null&&!inline.contains(im.optString("file")))return true;}return false;}
 static void appendImages(MainActivity a,LinearLayout parent,Note n,boolean hidden,boolean editing){for(int i=0;i<n.images.length();i++){JSONObject im=n.images.optJSONObject(i);if(im==null)continue;if(InlineImageText.files(n.body+"\n"+n.answer).contains(im.optString("file")))continue;ImageMaskView v=new ImageMaskView(a,im,hidden,editing);parent.addView(v,new LinearLayout.LayoutParams(-1,a.u.dp(250)));Button b=a.u.button(hidden?"사진 확대 (가림 유지)":"사진 확대",()->dialog(a,im,false,()->{},hidden));parent.addView(b);}}
 static void dialog(MainActivity a,JSONObject image,boolean edit,Runnable changed){dialog(a,image,edit,changed,false);}
 static void dialog(MainActivity a,JSONObject image,boolean edit,Runnable changed,boolean hidden){LinearLayout layout=a.u.col();layout.setPadding(a.u.dp(12),a.u.dp(8),a.u.dp(12),a.u.dp(8));ImageMaskView view=new ImageMaskView(a,image,hidden,edit);layout.addView(a.u.text(edit?"가릴 곳을 손가락으로 드래그하세요.":"두 손가락으로 확대 · 한 손가락으로 이동",14,a.u.muted));layout.addView(view,new LinearLayout.LayoutParams(-1,a.u.dp(380)));if(edit){layout.addView(a.u.button("마지막 가림 지우기",()->{JSONArray m=image.optJSONArray("masks");if(m!=null&&m.length()>0)m.remove(m.length()-1);view.invalidate();}));layout.addView(a.u.button("모든 가림 지우기",()->a.u.confirm("가림 지우기","이 사진의 모든 가림 영역을 지울까요?",()->{try{image.put("masks",new JSONArray());view.invalidate();}catch(Exception e){a.error(e);}})));}AlertDialog d=new AlertDialog.Builder(a).setTitle(edit?"사진 가림 설정":"사진 확대").setView(layout).setPositiveButton("완료",(x,w)->changed.run()).create();d.setOnDismissListener(x->changed.run());d.show();}
 static String importImage(Context c,Uri uri)throws IOException {File dir=new File(c.getFilesDir(),"images");if(!dir.exists()&&!dir.mkdirs())throw new IOException("사진 저장 공간을 만들 수 없습니다");String name=UUID.randomUUID()+".img";File out=new File(dir,name);boolean success=false;try(InputStream in=c.getContentResolver().openInputStream(uri);OutputStream dst=new FileOutputStream(out)){if(in==null)throw new IOException("사진을 열 수 없습니다");byte[] b=new byte[32768];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>25L*1024*1024)throw new IOException("사진은 한 장당 25MB까지 첨부할 수 있습니다");dst.write(b,0,n);}success=true;}finally{if(!success)out.delete();}BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(out.getPath(),bounds);if(bounds.outWidth<=0||bounds.outHeight<=0){out.delete();throw new IOException("지원하지 않는 사진 형식입니다");}return name;}
}
